// src/components/pages/Landing.jsx
import React from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import PageWrapper from "../PageWrapper";

const Landing = () => {
  const navigate = useNavigate();

  return (
    <PageWrapper>
      <div className="flex flex-col items-center justify-center min-h-screen px-6 bg-gradient-to-br from-gray-900 via-black to-gray-800 text-white text-center">

        {/* Heading */}
        <motion.h1
          initial={{ y: -40, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.8 }}
          className="text-5xl md:text-6xl font-extrabold mb-6"
          style={{ fontFamily: "'Poppins', 'Inter', sans-serif" }}
        >
          Welcome to <span className="text-indigo-500">AI Interview Coach</span>
        </motion.h1>

        {/* Subheading */}
        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
          className="max-w-2xl text-gray-300 text-lg mb-10"
        >
          Get personalized, AI-powered feedback to boost your confidence and improve your interview performance.
        </motion.p>

        {/* Start Learning Button */}
        <motion.button
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.95 }}
          onClick={() => navigate("/login")}
          className="bg-gradient-to-r from-indigo-500 to-purple-500 hover:from-purple-500 hover:to-indigo-500 text-white font-semibold text-lg px-10 py-4 rounded-full shadow-xl transition-all duration-300"
        >
          Start Learning 🚀
        </motion.button>

        {/* Optional: Small footer note on landing */}
        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.6 }}
          className="mt-6 text-gray-400 text-sm"
        >
          Already have an account? <span className="underline cursor-pointer" onClick={() => navigate("/login")}>Login</span>
        </motion.p>

      </div>
    </PageWrapper>
  );
};

export default Landing;
